#!/usr/bin/env node
/**
 * claude-workflow-kit Installer
 *
 * Kopiert die dreizehn Skills nach ~/.claude/skills/ oder ./.claude/skills/,
 * schreibt .claude/workflow.config.json und .claude/kit/board.mjs.
 *
 * Aufruf:
 *   node install.mjs
 *   node install.mjs --version
 *   npx github:mannewolff/claude-workflow-kit  (nach Veroeffentlichung)
 *
 * Aenderung v1.3.0: Config-Schema nutzt codeHost + issueTracker statt provider.
 * Bestehende Configs mit provider werden beim Lesen still migriert (abwaertskompatibel).
 */

import { createInterface } from "node:readline";
import { existsSync, mkdirSync, writeFileSync, readFileSync, readdirSync, statSync, chmodSync } from "node:fs";
import { spawnSync } from "node:child_process";
import { resolve, join } from "node:path";
import { homedir } from "node:os";

// Kein __dirname mehr: Seit Issue #499 liest der Installer keine Datei neben sich
// — alles Ausgelieferte steht als Base64-Konstante in dieser Datei.

const VERSION = "1.50.0";

// --- CLAUDE-workflow.md (Base64-eingebettet fuer Single-File-Portabilitaet) ---
// SYNC: Nach jeder Aenderung an templates/CLAUDE-workflow.md neu generieren:
//   node tools/sync-blobs.mjs        (Pruefung: node tools/sync-blobs.mjs --check)
const CONFIG_EXAMPLE_B64 = "";
const CLAUDE_WORKFLOW_MD_B64 = "";

// --- Gate-Register (Base64-eingebettet fuer Single-File-Portabilitaet) ---
// Die beiden Register benennen die Regeln, gegen die eine fachliche Anforderung bzw. ein
// Plandokument verstossen kann. Sie gehoeren neben CLAUDE-workflow.md in dasselbe
// Zielverzeichnis: `/kontext` laedt sie ueber projectDocs (".claude/CLAUDE-*"), und
// `/issue-review` braucht sie, um einen Fund als `gate` zu klassifizieren.
// SYNC: Nach jeder Aenderung an templates/CLAUDE-Fachplan.md bzw. templates/CLAUDE-Plan.md:
//   node tools/sync-blobs.mjs        (Pruefung: node tools/sync-blobs.mjs --check)
const CLAUDE_FACHPLAN_MD_B64 = "";
const CLAUDE_PLAN_MD_B64 = "";

// --- board.mjs (Base64-eingebettet fuer Single-File-Portabilitaet) ---
// SYNC: Nach jeder Aenderung an kit/board.mjs neu generieren:
//   node tools/sync-blobs.mjs        (Pruefung: node tools/sync-blobs.mjs --check)
const BOARD_MJS_B64 = "";

// --- night.mjs (Base64-eingebettet fuer Single-File-Portabilitaet) ---
// SYNC: Nach jeder Aenderung an kit/night.mjs neu generieren:
//   node tools/sync-blobs.mjs        (Pruefung: node tools/sync-blobs.mjs --check)
const NIGHT_MJS_B64 = "";

// --- checks.mjs (Base64-eingebettet fuer Single-File-Portabilitaet) ---
// SYNC: Nach jeder Aenderung an kit/checks.mjs neu generieren:
//   node tools/sync-blobs.mjs        (Pruefung: node tools/sync-blobs.mjs --check)
const CHECKS_MJS_B64 = "";

// --- spec.mjs (Base64-eingebettet fuer Single-File-Portabilitaet) ---
// SYNC: Nach jeder Aenderung an kit/spec.mjs neu generieren:
//   node tools/sync-blobs.mjs        (Pruefung: node tools/sync-blobs.mjs --check)
// SYNC: Nach jeder Aenderung an .githooks/gate.mjs neu generieren
//   node tools/sync-blobs.mjs
const GATE_MJS_B64 = "";
// SYNC: Nach jeder Aenderung an .githooks/pre-commit neu generieren
const PRE_COMMIT_B64 = "";
const SPEC_MJS_B64 = "";

// --- Skills (Base64-eingebettet fuer Single-File-Portabilitaet) ---
// JSON { skillName: { dateiname: inhalt } } fuer alle Skill-Ordner unter skills/.
// SYNC: Nach jeder Aenderung an skills/<name>/ neu generieren:
//   node tools/sync-blobs.mjs        (Pruefung: node tools/sync-blobs.mjs --check)
const SKILLS_B64 = "";

// --- Defaults (eingebettet, damit install.mjs als Single-File portabel ist) ---
const schema = {
  defaults: {
    codeHost: "github",
    issueTracker: "github",
    buildChecks: [],
    mutationCommand: "",
    mainBranch: "main",
    productionBranch: "production",
    reviewScope: "diff",
    reviewModel: "claude-opus-4-8",
    triggers: { go: "GO", push: "push main", merge: "merge production" },
    local: { issuesDir: "issues" },
    columns: {
      backlog:     "Backlog",
      ready:       "Ready",
      in_progress: "In progress",
      in_review:   "In review",
      done:        "Done",
    },
  },
  validationRules: [
    {
      field: "codeHost",
      rule: "enum",
      allowed: ["github", "gitlab", "local"],
      error: "codeHost muss 'github', 'gitlab' oder 'local' sein.",
    },
    {
      field: "issueTracker",
      rule: "enum",
      // 'toolbox' ist bewusst nicht in Prompt und Fehlermeldung (Hidden Feature, #0013),
      // muss aber gueltig sein, damit eine bestehende Toolbox-Config beim Re-Install
      // per Enter bestaetigt werden kann (#124).
      allowed: ["github", "gitlab", "local", "toolbox"],
      error: "issueTracker muss 'github', 'gitlab' oder 'local' sein.",
    },
    {
      field: "reviewScope",
      rule: "enum",
      allowed: ["diff", "full"],
      error: "reviewScope muss 'diff' oder 'full' sein.",
    },
    {
      field: "reviewModel",
      rule: "pattern",
      pattern: "^claude-",
      error: "reviewModel muss eine Claude-Modell-ID sein (z.B. 'claude-opus-4-8').",
    },
    // Das Reviewer-Paar (Issue #432/#433). `validate()` arbeitet feldlokal und prueft
    // genau ein Feld — zum Zeitpunkt der reviewModel-Frage ist reviewCommand noch gar
    // nicht erfragt. Diese Regel braucht deshalb beide Werte und laeuft als
    // Gesamtpruefung nach der letzten der beiden Fragen (validateFelder).
    //
    // Die Meldung erklaert das Paar, statt nur "falsch" zu sagen: Wer sie liest, sitzt
    // vor einem abgebrochenen Installer und muss ohne Doku wissen, welches der beiden
    // Felder er wegnimmt.
    {
      fields: ["reviewModel", "reviewCommand"],
      rule: "exactlyOne",
      error:
        "Genau eines von reviewModel und reviewCommand muss gesetzt sein.\n" +
        "    reviewModel   = ein Claude-Modell, das als Reviewer-Subagent laeuft; es muss\n" +
        "                    mit 'claude-' beginnen (z.B. 'claude-opus-4-8').\n" +
        "    reviewCommand = eine fremde CLI, die den Review-Prompt ueber stdin bekommt\n" +
        "                    (z.B. 'codex exec --model gpt-5').\n" +
        "    Fuer einen Kommando-Reviewer: reviewModel mit '-' leeren.\n" +
        "    Fuer den Claude-Reviewer: reviewCommand mit '-' leeren.",
    },
  ],
};
const DEFAULTS = schema.defaults;

// --- Stdin-Lese-Infrastruktur ---
// Liest alle Zeilen vorab wenn kein TTY (Pipe/CI), liefert sie der Reihe nach.
// Im TTY-Modus nutzt readline normal interaktiv.

// KIT_INSTALL_TTY ist ein Test-Hook (Issue #497, dasselbe Muster wie KIT_ROOT in
// kit/night.mjs, Issue #189): Er erzwingt die TTY-Fuehrung der Fragen und macht
// damit `rl.question` in `ask` erreichbar, dazu beide Zweige der Bedingung in
// `loadPipedLines` und des Ternaers in `main`. Ohne ihn ist der Weg im Testlauf
// unerreichbar — dort ist stdin nie eine TTY. Ein leerer Wert gilt als nicht
// gesetzt; ohne gesetzten Wert entscheidet allein `process.stdin.isTTY` wie
// bisher.
//
// Die Entscheidung steht bewusst an EINER Stelle: Zwei getrennte Lesestellen
// liessen sich einzeln umschalten, und der Installer fragte dann auf dem einen
// Weg interaktiv und auf dem anderen nicht.
const IST_TTY = Boolean(process.env.KIT_INSTALL_TTY) || Boolean(process.stdin.isTTY);

let _pipedLines = null;

async function loadPipedLines() {
  if (IST_TTY) return;
  _pipedLines = [];
  for await (const line of createInterface({ input: process.stdin, crlfDelay: Infinity })) {
    _pipedLines.push(line);
  }
}

function ask(rl, question) {
  if (_pipedLines !== null) {
    const line = _pipedLines.shift() ?? "";
    process.stdout.write(question + line + "\n");
    return Promise.resolve(line);
  }
  return new Promise((resolve) => rl.question(question, resolve));
}

// --- Hilfsfunktionen ---

function validate(field, value) {
  const rules = schema.validationRules || [];
  for (const rule of rules) {
    if (rule.field !== field) continue;
    if (rule.rule === "enum" && !rule.allowed.includes(value)) {
      return rule.error;
    }
    // Ein leerer Wert heisst "nicht gesetzt"; Muster gelten fuer gesetzte Werte. Ohne
    // diese Ausnahme liesse sich reviewModel nie leeren — die ^claude-Regel wuerde
    // genau die Eingabe abweisen, mit der man auf einen Kommando-Reviewer wechselt
    // (Issue #433). Dass ueberhaupt eines der beiden Felder gesetzt ist, sichert die
    // exactlyOne-Regel.
    if (rule.rule === "pattern" && value !== "" && !new RegExp(rule.pattern).test(value)) {
      return rule.error;
    }
  }
  return null;
}

// Regeln ueber MEHRERE Felder, geprueft, wenn alle beteiligten Antworten vorliegen.
// `werte` ist ein Objekt Feldname → Antwort; ein leerer Wert gilt als nicht gesetzt.
function validateFelder(werte) {
  const rules = schema.validationRules || [];
  for (const rule of rules) {
    if (rule.rule !== "exactlyOne") continue;
    const gesetzt = rule.fields.filter((f) => (werte[f] ?? "") !== "");
    if (gesetzt.length !== 1) return rule.error;
  }
  return null;
}

// Eingabe, die ein Feld bewusst LEERT. Eine leere Eingabe bedeutet in askWithDefault
// "Default uebernehmen" — "kein Wert" waere damit gar nicht ausdrueckbar, solange ein
// Default gesetzt ist. Nur die beiden Reviewer-Fragen sind leerbar (Issue #433).
const LEER_EINGABE = "-";

async function askWithDefault(rl, question, defaultValue, field, leerbar = false) {
  while (true) {
    const raw = await ask(rl, `${question} [${defaultValue}]: `);
    const eingabe = raw.trim();
    let value;
    if (leerbar && eingabe === LEER_EINGABE) value = "";
    else value = eingabe === "" ? defaultValue : eingabe;
    const error = field ? validate(field, value) : null;
    if (error) {
      console.error(`  Fehler: ${error}`);
      if (_pipedLines !== null) throw new Error(`Validation failed in non-interactive mode: ${error}`);
      continue;
    }
    return value;
  }
}

// KIT_INSTALL_BLOB_DEFEKT ist ein Test-Hook (Issue #497, dasselbe Muster wie
// KIT_ROOT in kit/night.mjs, Issue #189): Gesetzt, laesst er diese Funktion
// werfen und erreicht damit den catch in copySkills, als waere der Blob korrupt.
// Anders ist dieser Zweig nicht zu erreichen — SKILLS_B64 ist eine feste
// Konstante dieser Datei, und eine manipulierte Kopie erzeugt Coverage unter
// einem Temp-Pfad, den SonarCloud nicht auf install.mjs abbilden kann.
//
// Der Hook injiziert eine STOERUNG, keine Quelle: Sein Wert wird nur auf
// gesetzt/nicht gesetzt geprueft, nie geparst und nie in den Blob uebernommen.
// Er kann deshalb keinen Inhalt in die geschriebenen Skills einschleusen; seit
// Issue #499 fuehrt der Fehlerpfad direkt in den Abbruch, weil es keinen
// Dateisystem-Fallback mehr gibt. Ein leerer Wert gilt als nicht gesetzt, und
// ohne gesetzten Wert bleibt nur die Zeile darunter.
//
// KIT_INSTALL_BLOB_LEER ist der zweite Hook derselben Bauart (Issue #499): Er
// ergaenzt den gelesenen Blob um einen Eintrag OHNE Dateien und erreicht damit
// die Warnung, die genau diesen Fall meldet. Sonst waere sie an keiner Eingabe
// erreichbar — der ausgelieferte Blob enthaelt keinen leeren Eintrag, weil jeder
// Ordner unter skills/ eine SKILL.md traegt; erzeugen kann sync-blobs ihn aber
// jederzeit (buildDirJson schreibt einen Ordner ohne Dateien als {}).
// Auch er ist eine Stoerung, keine Quelle: Sein Wert wird nur auf gesetzt/nicht
// gesetzt geprueft, der Eintragsname ist eine feste Konstante dieser Datei, und
// ein Eintrag ohne Dateien schreibt per Definition nichts auf die Platte.
const BLOB_LEER_NAME = "blob-eintrag-ohne-dateien";

function skillsBlobLesen() {
  if (process.env.KIT_INSTALL_BLOB_DEFEKT) throw new Error("Test-Hook");
  const blob = JSON.parse(Buffer.from(SKILLS_B64, "base64").toString("utf-8"));
  if (process.env.KIT_INSTALL_BLOB_LEER) blob[BLOB_LEER_NAME] = {};
  return blob;
}

function copySkills(targetDir) {
  // Einzige Quelle: der eingebettete Blob (Single-File-Portabilitaet). Den
  // Rueckfall auf ein skills/ neben dem Installer gibt es seit Issue #499 nicht
  // mehr — er war unerreichbar: SKILLS_B64 ist eine versionierte Konstante dieser
  // Datei, die `tools/sync-blobs.mjs --check` als Pflicht-Check und ein eigener
  // CI-Workflow synchron halten. Damit liest der Installer kein Verzeichnis neben
  // sich mehr und ist ohne weiteren Repo-Kontext lauffaehig.
  let skillsBlob = {};
  if (SKILLS_B64) {
    try {
      skillsBlob = skillsBlobLesen();
    } catch {
      console.warn("  Warnung: eingebetteter Skills-Blob ist kein gueltiges JSON, wird ignoriert.");
    }
  }

  // Die Namen kommen aus dem Blob, frueher standen sie als feste Liste hier. Genau
  // daran ist /issue-review gescheitert: Der Skill lag im Blob, fehlte aber in der
  // Liste — und wurde in KEINEM per Installer eingerichteten Projekt jemals angelegt,
  // lautlos. Eine Liste, die man beim Hinzufuegen eines Skills pflegen muss, wird
  // irgendwann vergessen; der wiederkehrende Fehler gehoert mechanisch ausgeschlossen
  // statt der Sorgfalt ueberlassen (Leitplanken-Prinzip, Issue #122).
  const skills = Object.keys(skillsBlob);

  let copied = 0;
  for (const skill of skills) {
    const files = skillsBlob[skill];
    if (Object.keys(files).length === 0) {
      // Ohne Pfadangabe — es gibt keinen Pfad mehr. Stumm ueberspringen waere
      // schlimmer: Der Skill fehlte im Zielprojekt, ohne dass es jemand saehe.
      console.warn(`  Warnung: ${skill} ist im eingebetteten Blob leer, wird uebersprungen.`);
      continue;
    }
    const dest = join(targetDir, skill);
    mkdirSync(dest, { recursive: true });
    for (const [filename, content] of Object.entries(files)) {
      writeFileSync(join(dest, filename), content, "utf-8");
    }
    console.log(`  ✓ ${skill}`);
    copied++;
  }

  // Deckt alle Zustaende eines unbrauchbaren Blobs an einer Stelle ab: leerer
  // String, korruptes Base64/JSON, gueltiges {}, und ein Blob, dessen Eintraege
  // alle leer sind.
  if (copied === 0) {
    console.error(
      "Fehler: Kein einziger Skill konnte kopiert werden " +
      "(eingebetteter Blob fehlt oder ist beschaedigt)."
    );
    process.exit(1);
  }
  return copied;
}

// --- GitLab Label Setup ---

const GITLAB_LABELS = [
  { name: "Backlog",     color: "#e2e2e2" },
  { name: "Ready",       color: "#0075ca" },
  { name: "In progress", color: "#e4e669" },
  { name: "In review",   color: "#d93f0b" },
  { name: "Done",        color: "#0e8a16" },
];

async function setupGitLabLabels(rl) {
  const raw = await ask(rl, "\nGitLab-Labels jetzt automatisch anlegen? (glab muss eingeloggt sein) [j/n]: ");
  if (raw.trim().toLowerCase() !== "j") {
    console.log(`  Labels manuell anlegen: Backlog, Ready, "In progress", "In review", Done`);
    console.log(`  Wichtig: Leerzeichen in den Namen verwenden, kein Bindestrich.\n`);
    return;
  }
  console.log("\nLege GitLab-Labels an:");
  // Ohne Shell, mit Argument-Array (Issue #198, dieselbe Linie wie board.mjs in #196):
  // Zuvor wurde der Labelname in eine Kommandozeile interpoliert. Namen wie
  // "In progress" haengen damit am Quoting-Dialekt der jeweiligen Plattform, und ein
  // Sonderzeichen im Namen bricht den Aufruf ueberall. Als argv-Element gibt es das
  // Problem nicht.
  for (const label of GITLAB_LABELS) {
    const res = spawnSync("glab", ["label", "create", "--name", label.name, "--color", label.color], {
      encoding: "utf-8",
    });
    if (!res.error && res.status === 0) {
      console.log(`  ✓ ${label.name}`);
      continue;
    }
    const msg = res.error ? res.error.message : (res.stderr ?? "");
    if (msg.includes("already exists") || msg.includes("has already been taken")) {
      console.log(`  ~ ${label.name} (bereits vorhanden)`);
    } else {
      console.warn(`  ✗ ${label.name}: ${msg.trim()}`);
    }
  }
  console.log(`\n  Labels angelegt. Jetzt manuell das Board einrichten:`);
  console.log(`  Issues → Boards → "Add list" → je eine Spalte fuer jedes Label anlegen.`);
  console.log(`  Reihenfolge: Backlog → Ready → In progress → In review → Done`);
  console.log(`  (Board-Spalten lassen sich nicht per CLI anlegen — das ist eine GitLab-Einschraenkung.)\n`);
}

// --- Hauptprogramm ---

// Frage 1 (global/projekt) als eigene Schleife: haelt die Wiederholung aus main() heraus.
async function promptScope(rl) {
  while (true) {
    const raw = await ask(rl, "Skills global (~/.claude/skills/) oder nur fuer dieses Projekt (.claude/skills/)? [global/projekt]: ");
    const answer = raw.trim().toLowerCase();
    if (answer === "" || answer === "global") return "global";
    if (answer === "projekt") return "projekt";
    console.error("  Bitte 'global' oder 'projekt' eingeben.");
  }
}

// Fragen 7 und 8 (das Reviewer-Paar) als eigene Schleife, wie promptScope: Sie werden
// gemeinsam wiederholt, weil die Regel "genau eines von beiden" erst mit beiden Antworten
// pruefbar ist (Issue #433).
//
// Der leere Default fuer reviewModel gilt in zwei Faellen. Traegt die Bestandsconfig
// einen Kommando-Reviewer ALLEIN, ist das der ausloesende Fall aus Issue #433: Er soll
// sich per Enter bestaetigen lassen. Traegt sie BEIDE Felder nicht-leer, wird der
// Widerspruch hier aufgeloest, statt ihn nur abzuweisen — vorgeschlagen wurden sonst
// beide Bestandswerte und abgewiesen genau diese Kombination, und wer bestaetigt, was
// ihm vorgeschlagen wird, kam nicht heraus (Issue #480). Weil das Kommando ohne eigene
// Frage nicht rekonstruierbar waere, das Modell aber jederzeit neu eingetippt ist,
// behaelt reviewCommand seinen Bestandswert; still umgeschrieben wird nichts, der
// Hinweis unten benennt den Eingriff vor der ersten Frage.
const REVIEWER_WIDERSPRUCH_HINWEIS =
  "  Diese Config traegt beide Reviewer — gelten kann nur einer: reviewModel entfaellt,";

async function promptReviewerPaar(rl, D, existingConfig) {
  const beideGesetzt = Boolean(existingConfig.reviewModel && existingConfig.reviewCommand);
  const reviewModelDefault =
    beideGesetzt || (existingConfig.reviewCommand && !existingConfig.reviewModel)
      ? ""
      : D.reviewModel;

  if (beideGesetzt) {
    console.log(`\n${REVIEWER_WIDERSPRUCH_HINWEIS}`);
    console.log(`  reviewCommand bleibt: ${existingConfig.reviewCommand}`);
    console.log(`  Umgekehrt: reviewCommand mit '${LEER_EINGABE}' leeren und reviewModel eintragen.`);
  }

  while (true) {
    const reviewModel = await askWithDefault(
      rl,
      `Reviewer-Modell (Claude-Subagent, beginnt mit 'claude-'; '${LEER_EINGABE}' = keines)`,
      reviewModelDefault,
      "reviewModel",
      true
    );
    const reviewCommand = await askWithDefault(
      rl,
      `Reviewer-Kommando (fremde CLI, Prompt ueber stdin; '${LEER_EINGABE}' = keines)`,
      D.reviewCommand ?? "",
      "reviewCommand",
      true
    );
    const fehler = validateFelder({ reviewModel, reviewCommand });
    if (!fehler) return { reviewModel, reviewCommand };
    console.error(`  Fehler: ${fehler}`);
    // Interaktiv werden genau diese beiden Fragen erneut gestellt; die uebrigen
    // Antworten bleiben stehen. Im Pipe-Modus antwortet niemand nach — dort bricht es ab.
    if (_pipedLines !== null) throw new Error(`Validation failed in non-interactive mode: ${fehler}`);
  }
}

// Frage 9 (nur projektlokal): das beschriebene Verhalten unter specs/ (Issue #439).
//
// Die einzige Frage des Installers, deren Antwort sich nicht zurueckholen laesst: Das
// Vorhandensein des spec-Blocks IST der Schalter — es gibt kein Feld 'enabled' und
// damit keinen Aus-Zustand (Issue #438). Deshalb steht der Hinweis VOR dem Prompt;
// hinter ihm gelesen kaeme er zu spaet.
//
// Eigene Schleife wie promptScope: Sie kennt nur j/n und traegt ihre Wiederholung
// selbst. askWithDefault passt nicht — dessen Default-Semantik ("leer = Default
// uebernehmen") gilt hier zwar auch, aber die Antwort ist ein Wahrheitswert, kein
// Feld der Config.
// Der Vorspann nennt die Sache beim Namen, bevor er vor ihrer Unumkehrbarkeit warnt
// (Issue #481): Wer das Vorhaben nicht selbst gebaut hat, entschied sonst dauerhaft
// ueber etwas, dessen Namen und Wirkung er nicht kennt. Drei Angaben tragen das —
// Methode, Wirkung auf die taegliche Arbeit, Stelle zum Nachlesen; die einzelnen
// beruehrten Arbeitsschritte bleiben draussen, sie machten den Block lang statt klar.
//
// Der Umkehr-Hinweis begruendet an der Sache statt am Aufbau der Config und verspricht
// nicht mehr, als die Doku zusichert: Das Kit BIETET kein Zuruecknehmen an — von Hand
// aus der Config entfernen laesst der Block sich sehr wohl.
const SPEC_VORSPANN = [
  "  Spec-Driven Development (SDD): Das Projekt fuehrt unter specs/ eine Spec — die",
  "  verbindliche Beschreibung seines Verhaltens.",
  "  Sie wirkt bei jedem Arbeitspaket und jedem Push: Was sich am Verhalten aendert, wird",
  "  in der Spec nachgezogen und von einem Test belegt, sonst weist das Gate es ab.",
  '  Zum Nachlesen: Abschnitt "Beschriebenes Verhalten" in docs/dokumentation.md.',
  "",
  "  Diese Entscheidung ist nicht zurueckzunehmen: Ab spec.seit misst das Gate jedes",
  "  Arbeitspaket an der Spec, und das Kit bietet kein Zuruecknehmen an — kein Kommando,",
  "  keine Frage, keine Option. (Der Block in der Config ist selbst der Schalter.)",
];

async function promptSpec(rl) {
  console.log(`\n${SPEC_VORSPANN.join("\n")}`);
  while (true) {
    const raw = await ask(rl, "Soll dieses Projekt eine Spec fuehren (Spec-Driven Development)? [j/N]: ");
    const antwort = raw.trim().toLowerCase();
    if (antwort === "j" || antwort === "ja") return true;
    if (antwort === "" || antwort === "n" || antwort === "nein") return false;
    // Eine unverstaendliche Antwort still als Nein zu werten hiesse, eine Entscheidung
    // zu erfinden, die niemand getroffen hat. Interaktiv wird nachgefragt, im
    // Pipe-Modus bricht es ab — wie bei askWithDefault, dort antwortet niemand nach.
    const fehler = "Bitte 'j' oder 'n' eingeben.";
    console.error(`  Fehler: ${fehler}`);
    if (_pipedLines !== null) throw new Error(`Validation failed in non-interactive mode: ${fehler}`);
  }
}

// Tagesdatum lokal statt per toISOString(), wie in kit/board.mjs: Um 00:30 MESZ liefert
// UTC den Vortag — und an spec.seit haengt spaeter das Gate.
function heute() {
  const jetzt = new Date();
  const zweistellig = (n) => String(n).padStart(2, "0");
  return `${jetzt.getFullYear()}-${zweistellig(jetzt.getMonth() + 1)}-${zweistellig(jetzt.getDate())}`;
}

// Liefert den neuen spec-Block — oder null, wenn nicht gefragt wird oder die Antwort
// Nein lautet. Die beiden Bedingungen stehen hier statt in main(): Sie gehoeren zur
// Frage, nicht zum Ablauf, und main() traegt schon genug Verzweigungen.
//
// Bei `global` entfaellt die Frage: spec.bereiche sind Code-Globs EINES Projekts, und
// ein Block in ~/.claude/workflow.config.json haette jedes Projekt eingeschaltet, ohne
// dass es dort entschieden wurde.
//
// Ist der Block schon da, wird ebenfalls nicht gefragt — ein 'Nein' duerfte ihn sonst
// entfernen, und damit boete der Installer genau den Weg zurueck an, den es nicht gibt.
//
// 'bereiche' traegt einen erkennbaren Platzhalter statt eines geratenen Musters: Der
// Installer kennt die Codebasis nicht (Plan #437, A8), ein leeres Objekt waere aber
// schemawidrig (#438 verlangt minProperties: 1) und die Config damit ungueltig.
// Auch der Tracker entscheidet mit (A19, Issue #461): 'github' und 'gitlab' tragen das
// beschriebene Verhalten nicht — dort gibt es weder Aktivitaetsverlauf noch Suche ueber
// Aussagen. Die Frage entfaellt dann ersatzlos, statt eine Entscheidung anzubieten, die
// der Installer anschliessend nicht einloest: spec.mjs wuerde jeden Lauf abweisen.
// --- Das Commit-Gate einhaengen (Issue #473, Plan #467 A2/A11) --------------
//
// Der Hook wandert mit dem Clone, die AKTIVIERUNG nicht: `core.hooksPath` ist lokale
// git-Config. Ein frischer Clone hat die Dateien und kein wirksames Gate, bis jemand
// den Installer laufen laesst — das steht so in der Doku, statt eine Zusicherung zu
// behaupten, die git nicht hergibt.

/** Die Kennungszeile, an der ein von uns geschriebener Hook erkennbar ist. */
const HOOK_KENNUNG = "# claude-workflow-kit pre-commit";

function gitAntwort(...args) {
  const res = spawnSync("git", args, { encoding: "utf-8" });
  // ENOENT: git fehlt im PATH. Kein Repo: Exit ungleich 0. Beides ist kein Abbruch —
  // die Installer-Fixtures sind keine Git-Repos, und ausserhalb eines Repos soll der
  // Installer benutzbar bleiben.
  if (res.error || res.status !== 0) return null;
  return (res.stdout || "").trim();
}

/** Ist das Arbeitsverzeichnis ein Git-Repo mit erreichbarem git? */
function imGitRepo() {
  return gitAntwort("rev-parse", "--git-dir") !== null;
}

/**
 * Liegt im Hooks-Verzeichnis eine AKTIVE Datei?
 *
 * `git init` legt `*.sample`-Dateien an; ohne diesen Ausschluss gaelte jedes frische
 * Repo als belegt. `git rev-parse --git-path hooks` statt `.git/hooks` deckt zugleich
 * Worktrees und Submodule ab, wo `.git` eine Datei ist.
 */
function aktiverHookVorhanden() {
  const hooks = gitAntwort("rev-parse", "--git-path", "hooks");
  if (!hooks || !existsSync(hooks)) return false;
  try {
    return readdirSync(hooks).some((n) => !n.endsWith(".sample")
      && statSync(join(hooks, n)).isFile());
  } catch {
    return false;
  }
}

/**
 * Was mit `core.hooksPath` geschehen soll — entschieden VOR der Frage.
 *
 * Gelesen wird der EFFEKTIVE Wert (ohne `--local`): Ein global gesetzter hooksPath
 * wuerde durch einen lokalen Eintrag fuer dieses Repo ausgehebelt, und genau das ist
 * der A11-Fall.
 */
function hooksPathLage(scope) {
  if (scope !== "projekt") return { art: "entfaellt", grund: "globaler Install" };
  if (!imGitRepo()) return { art: "entfaellt", grund: "kein Git-Repo oder git nicht gefunden" };
  const wert = gitAntwort("config", "--get", "core.hooksPath");
  if (wert === ".githooks") return { art: "schon gesetzt" };
  if (wert) return { art: "belegt", wert };
  if (aktiverHookVorhanden()) return { art: "belegt", wert: "eine aktive Datei im Hooks-Verzeichnis" };
  return { art: "frei" };
}

async function promptHooks(rl) {
  console.log("\n  Das Commit-Gate weist jeden Commit ab, dem kein gruener");
  console.log("  `node .claude/kit/checks.mjs run` auf demselben Stand vorausging.");
  console.log("  Dafuer setzt der Installer `git config core.hooksPath .githooks` —");
  console.log("  eine Aenderung an der git-Config dieses Repos.");
  while (true) {
    const raw = await ask(rl, "Soll das Commit-Gate eingehaengt werden? [j/N]: ");
    const antwort = raw.trim().toLowerCase();
    if (antwort === "j" || antwort === "ja") return true;
    if (antwort === "" || antwort === "n" || antwort === "nein") return false;
    const fehler = "Bitte 'j' oder 'n' eingeben.";
    console.error(`  Fehler: ${fehler}`);
    if (_pipedLines !== null) throw new Error(`Validation failed in non-interactive mode: ${fehler}`);
  }
}

/**
 * Fragt nur, wo die Frage etwas bewirkt — und verbraucht sonst KEINE Antwortzeile.
 * Im Pipe-Modus ist das der Unterschied zwischen gruen und rot: Jede ungefragte Frage
 * verschoebe alle folgenden Antworten.
 */
async function frageHooksPath(rl, scope) {
  const lage = hooksPathLage(scope);
  if (lage.art === "frei") return { setzen: await promptHooks(rl), lage };
  return { setzen: false, lage };
}

/**
 * Schreibt Hook und Gate nach `.githooks/` und haengt sie ein, wenn der Mensch
 * zugestimmt hat.
 *
 * Eigene Funktion und nicht in main(): Die vier Lagen von `core.hooksPath` plus der
 * Fremdhook-Fall traegen main() ueber die Komplexitaetsschwelle, die dieses Repo
 * seit Issue #401 haelt.
 *
 * Nach `.githooks/` und NICHT nach `.claude/kit/`: Der von ensureProjectGitignore
 * geschriebene Block schliesst `.claude/*` aus, und ein Clone haette den Hook dann
 * ohne das Programm, das er aufruft — er wiese jeden Commit ab.
 */
function schreibeCommitGate(scope, hooks) {
  // Die Bedingung steht hier und nicht in main(): Dort traegt sie einen Zweig mehr,
  // und main() liegt genau auf der Komplexitaetsschwelle.
  if (scope !== "projekt") return;
  const hooksDir = resolve(".githooks");
  mkdirSync(hooksDir, { recursive: true });
  const gateTarget = join(hooksDir, "gate.mjs");
  writeFileSync(gateTarget, Buffer.from(GATE_MJS_B64, "base64").toString("utf-8"), "utf-8");
  console.log(`✓ gate.mjs geschrieben: ${gateTarget}`);

  schreibeHookDatei(join(hooksDir, "pre-commit"));
  meldeHooksPath(hooks);
}

/**
 * Ein fremder Hook wird nicht ueberschrieben: `.githooks/` ist eine verbreitete
 * Konvention, und ein Projekt kann dort laengst einen eigenen fahren. Erkennbar ist
 * unserer an der Kennungszeile — ein Dateivergleich schluege bei jeder Version fehl.
 */
function schreibeHookDatei(hookTarget) {
  if (existsSync(hookTarget) && !readFileSync(hookTarget, "utf-8").includes(HOOK_KENNUNG)) {
    console.log(`! ${hookTarget} stammt nicht aus diesem Kit — unveraendert gelassen.`);
    console.log("  Zum Einhaengen des Gates dort ergaenzen: node .githooks/gate.mjs pre-commit");
    return;
  }
  writeFileSync(hookTarget, Buffer.from(PRE_COMMIT_B64, "base64").toString("utf-8"), "utf-8");
  try {
    chmodSync(hookTarget, 0o755);
  } catch {
    // Windows kennt kein x-Bit; chmod ist dort wirkungslos und kein Grund abzubrechen.
  }
  console.log(`✓ pre-commit geschrieben: ${hookTarget}`);
}

/** Setzt `core.hooksPath` oder sagt, warum nicht. */
function meldeHooksPath(hooks) {
  if (hooks.setzen) {
    const res = spawnSync("git", ["config", "core.hooksPath", ".githooks"], { encoding: "utf-8" });
    if (res.error || res.status !== 0) {
      console.error(`  Fehler: core.hooksPath liess sich nicht setzen: ${(res.stderr || res.error?.message || "").trim()}`);
      process.exitCode = 1;
      return;
    }
    console.log("✓ core.hooksPath auf .githooks gesetzt — das Commit-Gate ist aktiv.");
    return;
  }
  if (hooks.lage.art === "belegt") {
    console.log(`! core.hooksPath ist bereits ${hooks.lage.wert} — nicht geaendert.`);
    console.log("  Zum Einhaengen den eigenen Hook um 'node .githooks/gate.mjs pre-commit' ergaenzen.");
    return;
  }
  if (hooks.lage.art === "entfaellt") {
    console.log(`! core.hooksPath nicht gesetzt (${hooks.lage.grund}) — das Gate ist nicht aktiv.`);
    return;
  }
  if (hooks.lage.art === "schon gesetzt") {
    console.log("✓ core.hooksPath steht bereits auf .githooks.");
    return;
  }
  console.log("! core.hooksPath nicht gesetzt — das Gate ist nicht aktiv.");
}

const TRACKER_OHNE_SPEC = new Set(["github", "gitlab"]);

async function frageSpecBlock(rl, scope, existingConfig, issueTracker) {
  if (scope !== "projekt" || existingConfig.spec) return null;
  if (TRACKER_OHNE_SPEC.has(issueTracker)) return null;
  if (!(await promptSpec(rl))) return null;
  return { seit: heute(), bereiche: { beispiel: ["src/**"] } };
}

// Bestehende workflow.config.json als Update-Defaults laden und das alte provider-Feld
// (Rueckwaertskompatibilitaet) auf codeHost/issueTracker migrieren.
function loadExistingConfig(configPath) {
  let existingConfig = {};
  if (existsSync(configPath)) {
    try {
      existingConfig = JSON.parse(readFileSync(configPath, "utf-8"));
      console.log("  Bestehende workflow.config.json gefunden — Werte als Defaults uebernommen.\n");
    } catch {
      console.warn("  Hinweis: Bestehende workflow.config.json konnte nicht gelesen werden.\n");
    }
  }
  if (existingConfig.provider && !existingConfig.codeHost) existingConfig.codeHost = existingConfig.provider;
  if (existingConfig.provider && !existingConfig.issueTracker) existingConfig.issueTracker = existingConfig.provider;
  return existingConfig;
}

// .gitignore-Block fuer .claude/ (Issue #208).
//
// workflow.config.json gehoert ins Repository: buildChecks, columns, Branch-Namen und
// Tracker muessen fuer alle gleich sein. Lag die Datei ausserhalb, hatte jeder seine
// eigene Fassung — und eine abweichende columns-Fassung fuehrt nicht zu einem Fehler,
// sondern zu einer leeren Issue-Liste.
//
// Die erste Zeile MUSS `.claude/*` lauten, nicht `.claude/`: Git wertet ein
// !-Negationsmuster nicht aus, wenn das Verzeichnis selbst ausgeschlossen ist — es
// betritt es gar nicht erst. Mit `.claude/` bliebe die Negation wirkungslos, und der
// Fehler faehlt sich an wie "vergessen zu committen".
//
// Die letzten beiden Zeilen sind formal redundant (`.claude/*` deckt sie), stehen aber
// bewusst da: Sie machen lesbar, dass persoenliche Config und Metadaten-Cache
// absichtlich draussen bleiben.
const GITIGNORE_BLOCK = [
  "# claude-workflow-kit (Issue #208): workflow.config.json gehoert ins Repo,",
  "# alles andere unter .claude/ ist lokaler Zustand.",
  ".claude/*",
  "!.claude/workflow.config.json",
  ".claude/workflow.config.local.json",
  ".claude/board-meta-cache.json",
];

// '.claude/'-Regeln im projektlokalen .gitignore sicherstellen (idempotent).
function ensureProjectGitignore() {
  const gitignorePath = resolve(".gitignore");
  const content = existsSync(gitignorePath) ? readFileSync(gitignorePath, "utf-8") : "";
  const lines = content.split("\n");
  const trimmed = lines.map((l) => l.trim());

  if (trimmed.includes("!.claude/workflow.config.json")) {
    console.log("✓ .gitignore: .claude-Block bereits vorhanden");
    return;
  }

  // Eine handgepflegte .claude-Konfiguration nicht still umschreiben — das waere ein
  // Uebergriff. Nur melden, welcher Block empfohlen ist.
  const eigeneRegeln = trimmed.some((l) => l.startsWith(".claude/") && l !== ".claude/") ||
    trimmed.some((l) => l.startsWith("!.claude/"));
  if (eigeneRegeln) {
    console.log("! .gitignore: eigene .claude-Regeln gefunden — nichts geaendert.");
    console.log("  Empfohlen, damit workflow.config.json versionierbar bleibt:");
    for (const zeile of GITIGNORE_BLOCK) console.log(`    ${zeile}`);
    return;
  }

  const alteZeile = trimmed.indexOf(".claude/");
  if (alteZeile !== -1) {
    // Migration: ersetzen, nicht ergaenzen. Bliebe `.claude/` stehen, liefe die
    // Negation aus dem oben genannten Grund ins Leere.
    lines.splice(alteZeile, 1, ...GITIGNORE_BLOCK);
    writeFileSync(gitignorePath, lines.join("\n"), "utf-8");
    console.log("✓ .gitignore: '.claude/' durch Block ersetzt — workflow.config.json wird jetzt getrackt");
    return;
  }

  const block = GITIGNORE_BLOCK.join("\n") + "\n";
  const next = content.endsWith("\n") || content === "" ? content + block : content + "\n" + block;
  writeFileSync(gitignorePath, next, "utf-8");
  console.log("✓ .gitignore: .claude-Block eingetragen");
}

async function main() {
  if (process.argv.includes("--version")) {
    console.log(`claude-workflow-kit install.mjs v${VERSION}`);
    process.exit(0);
  }

  await loadPipedLines();
  const rl = IST_TTY
    ? createInterface({ input: process.stdin, output: process.stdout })
    : { close: () => {} };

  console.log("\n=== claude-workflow-kit Installer ===\n");
  console.log("Dieser Installer richtet die claude-workflow-kit-Skill-Bibliothek ein.");
  console.log("Zehn Fragen (bei globalem Install plus Vault-Pfad), dann bist du fertig.\n");

  // Frage 1: global oder projekt
  const scope = await promptScope(rl);

  // Bestehende Config als Defaults laden (Update-Modus)
  const existingConfigPath = scope === "global"
    ? join(homedir(), ".claude", "workflow.config.json")
    : resolve(".claude", "workflow.config.json");
  const existingConfig = loadExistingConfig(existingConfigPath);
  const D = { ...DEFAULTS, ...existingConfig };

  // Frage 2: codeHost
  const codeHost = await askWithDefault(
    rl,
    "Code-Host: 'github', 'gitlab' oder 'local'?",
    D.codeHost,
    "codeHost"
  );

  // Frage 3: issueTracker
  const issueTracker = await askWithDefault(
    rl,
    "Issue-Tracker: 'github', 'gitlab' oder 'local'?",
    D.issueTracker ?? codeHost,
    "issueTracker"
  );

  // Frage 4: mainBranch
  const mainBranch = await askWithDefault(rl, "Haupt-Branch (mainBranch)", D.mainBranch);

  // Frage 5: productionBranch
  const productionBranch = await askWithDefault(rl, "Production-Branch (productionBranch)", D.productionBranch);

  // Frage 6: reviewScope
  const reviewScope = await askWithDefault(
    rl,
    "Review-Umfang: 'diff' (nur Aenderungen) oder 'full' (gesamter Quelltext)?",
    D.reviewScope,
    "reviewScope"
  );

  // Frage 7 und 8: das Reviewer-Paar — genau eines von beiden (Issue #433).
  const { reviewModel, reviewCommand } = await promptReviewerPaar(rl, D, existingConfig);

  // Frage 9 (nur projektlokal, und nur wenn noch kein Block da ist): das beschriebene
  // Verhalten (Issue #439).
  const specBlock = await frageSpecBlock(rl, scope, existingConfig, issueTracker);

  // Frage 10 (nur projektlokal, und nur wenn core.hooksPath frei ist): das
  // Commit-Gate einhaengen (Issue #473).
  const hooks = await frageHooksPath(rl, scope);

  // Frage 11 (nur bei globalem Install): Vault-Pfad für kontext.config.json
  let vaultPath = "";
  if (scope === "global") {
    const raw = await ask(rl, "Pfad zum Memory-Vault für /kontext (leer = überspringen): ");
    vaultPath = raw.trim();
  }

  // --- Pfade berechnen ---
  const targetBase = scope === "global"
    ? join(homedir(), ".claude")
    : resolve(".claude");
  const skillsTarget = join(targetBase, "skills");
  const configTarget = join(targetBase, "workflow.config.json");
  const workflowMdTarget = join(targetBase, "CLAUDE-workflow.md");
  const fachplanMdTarget = join(targetBase, "CLAUDE-Fachplan.md");
  const planMdTarget = join(targetBase, "CLAUDE-Plan.md");

  // --- Skills kopieren ---
  console.log(`\nKopiere Skills nach ${skillsTarget}:`);
  const skillAnzahl = copySkills(skillsTarget);

  // --- Config schreiben ---
  // Basis sind die DEFAULTS (fuellen echte Luecken), darueber die bestehende Config
  // (nicht abgefragte Felder wie buildChecks, toolbox, github oder unbekannte
  // Zusatzfelder bleiben erhalten, #125), zuoberst die abgefragten Werte.
  const config = {
    ...DEFAULTS,
    ...existingConfig,
    codeHost,
    issueTracker,
    mainBranch,
    productionBranch,
    reviewScope,
  };
  // Das alte provider-Feld ist beim Laden auf codeHost/issueTracker migriert worden
  // und wird nicht zurueckgeschrieben.
  delete config.provider;
  // Das Reviewer-Paar wird als Paar geschrieben, nicht feldweise gespreadet: Genau
  // eines der beiden Felder steht in der Datei, das andere wird entfernt. Beide
  // Vorlagen fuellen sonst ein bewusst geleertes reviewModel wieder auf —
  // `schema.defaults.reviewModel` ueber den DEFAULTS-Spread und die Bestandsconfig
  // ueber ihren eigenen (Issue #433).
  if (reviewModel) {
    config.reviewModel = reviewModel;
    delete config.reviewCommand;
  } else {
    config.reviewCommand = reviewCommand;
    delete config.reviewModel;
  }
  // Der spec-Block entsteht nur auf ausdrueckliches Ja (Issue #439). Ein vorhandener
  // kommt ueber den existingConfig-Spread unveraendert mit — er wird hier weder
  // ergaenzt noch angefasst.
  if (specBlock) config.spec = specBlock;
  mkdirSync(targetBase, { recursive: true });
  writeFileSync(configTarget, JSON.stringify(config, null, 2) + "\n", "utf-8");
  console.log(`\n✓ Config geschrieben: ${configTarget}`);
  // Ohne diese Zeile merkt niemand, dass der Platzhalter ersetzt gehoert.
  if (specBlock) console.log("  spec.bereiche bitte von Hand pflegen.");

  // --- kontext.config.json schreiben (nur bei globalem Install mit Vault-Pfad) ---
  if (scope === "global" && vaultPath) {
    const kontextConfig = {
      vault: vaultPath,
      always: ["Index.md", "Profil.md"],
      projectDocs: ["CLAUDE-*", ".claude/CLAUDE-*"],
    };
    const kontextConfigTarget = join(targetBase, "kontext.config.json");
    writeFileSync(kontextConfigTarget, JSON.stringify(kontextConfig, null, 2) + "\n", "utf-8");
    console.log(`✓ kontext.config.json geschrieben: ${kontextConfigTarget}`);
  }

  // --- CLAUDE-workflow.md ablegen ---
  writeFileSync(workflowMdTarget, Buffer.from(CLAUDE_WORKFLOW_MD_B64, "base64").toString("utf-8"), "utf-8");
  console.log(`✓ CLAUDE-workflow.md abgelegt: ${workflowMdTarget}`);

  // --- Gate-Register ablegen ---
  writeFileSync(fachplanMdTarget, Buffer.from(CLAUDE_FACHPLAN_MD_B64, "base64").toString("utf-8"), "utf-8");
  console.log(`✓ CLAUDE-Fachplan.md abgelegt: ${fachplanMdTarget}`);
  writeFileSync(planMdTarget, Buffer.from(CLAUDE_PLAN_MD_B64, "base64").toString("utf-8"), "utf-8");
  console.log(`✓ CLAUDE-Plan.md abgelegt: ${planMdTarget}`);

  // --- Beispiel-Config ablegen ---
  //
  // Bewusst NEBEN die echte Config statt hinein: `issueReview.reviewers` haengt davon
  // ab, welche CLIs auf der Maschine liegen, und `pairs` ist eine Entscheidung, keine
  // Voreinstellung. Ein automatisch geschriebener Vier-Modelle-Block, von dem eines
  // fehlt, macht jeden Vorflug rot — genau deshalb steht `codex` nicht in der Vorlage.
  // Eine Datei zum Abschreiben ist ehrlicher als ein Default, der bei der Haelfte der
  // Nutzer nicht laeuft.
  //
  // Immer ueberschreiben: Sie enthaelt keine Nutzerdaten, und eine veraltete
  // Beispieldatei ist schlimmer als keine — sie zeigt dann Felder, die es nicht mehr
  // gibt. Das ist der Unterschied zur echten Config, die beim Re-Install erhalten
  // bleiben muss (Issue #125).
  const exampleTarget = join(targetBase, "workflow.config.example.json");
  writeFileSync(exampleTarget, Buffer.from(CONFIG_EXAMPLE_B64, "base64").toString("utf-8"), "utf-8");
  console.log(`✓ Beispiel-Config abgelegt: ${exampleTarget}`);

  // --- board.mjs ausschreiben ---
  const kitDir = join(targetBase, "kit");
  mkdirSync(kitDir, { recursive: true });
  const boardTarget = join(kitDir, "board.mjs");
  writeFileSync(boardTarget, Buffer.from(BOARD_MJS_B64, "base64").toString("utf-8"), "utf-8");
  console.log(`✓ board.mjs geschrieben: ${boardTarget}`);

  // --- night.mjs ausschreiben (Nacht-Runner, #131) ---
  const nightTarget = join(kitDir, "night.mjs");
  writeFileSync(nightTarget, Buffer.from(NIGHT_MJS_B64, "base64").toString("utf-8"), "utf-8");
  console.log(`✓ night.mjs geschrieben: ${nightTarget}`);

  // --- checks.mjs ausschreiben (Pruef-Auswahl, #425) ---
  // Die implement-Skills und /local-check rufen es als .claude/kit/checks.mjs auf;
  // ohne diesen Block laege es nur im Kit-Repo und der Aufruf ginge ins Leere.
  const checksTarget = join(kitDir, "checks.mjs");
  writeFileSync(checksTarget, Buffer.from(CHECKS_MJS_B64, "base64").toString("utf-8"), "utf-8");
  console.log(`✓ checks.mjs geschrieben: ${checksTarget}`);

  // --- spec.mjs ausschreiben (beschriebenes Verhalten, #441) ---
  // Wie checks.mjs: Die Skills rufen es als .claude/kit/spec.mjs auf; ohne diesen
  // Block laege es nur im Kit-Repo und der Aufruf ginge ins Leere.
  const specTarget = join(kitDir, "spec.mjs");
  writeFileSync(specTarget, Buffer.from(SPEC_MJS_B64, "base64").toString("utf-8"), "utf-8");
  console.log(`✓ spec.mjs geschrieben: ${specTarget}`);

  schreibeCommitGate(scope, hooks);

  // --- .gitignore ergänzen (nur projektlokal) ---
  if (scope === "projekt") ensureProjectGitignore();

  console.log("\n=== Fertig ===");
  console.log(`Starte eine neue Claude-Code-Session im Projekt.`);
  // Gezaehlt statt behauptet: Das Zahlwort stand hier zweimal falsch (zuletzt
  // "dreizehn" bei fuenfzehn Skills) — es wurde bei jedem neuen Skill vergessen.
  console.log(`Die ${skillAnzahl} Skills erscheinen in /help.\n`);
  if (scope === "projekt") {
    // Ohne diesen Hinweis bleibt die Datei ungetrackt liegen und niemand merkt es —
    // bis zwei Entwickler unterschiedliche buildChecks fahren (Issue #208).
    console.log(`Bitte .claude/workflow.config.json und .githooks/ committen — beide gelten fuer das ganze Team.`);
    console.log(`Persoenliche Abweichungen (reviewModel, reviewCommand, reviewScope) gehoeren in`);
    console.log(`.claude/workflow.config.local.json; die bleibt lokal.\n`);
  }
  if (codeHost === "gitlab" || issueTracker === "gitlab") {
    console.log(`GitLab: Stelle sicher dass 'glab auth login' durchgefuehrt wurde.`);
    await setupGitLabLabels(rl);
  } else if (codeHost === "github" || issueTracker === "github") {
    console.log(`GitHub: Stelle sicher dass 'gh auth login' durchgefuehrt wurde.\n`);
  }
  // rl erst hier schliessen — setupGitLabLabels fragt interaktiv nach
  rl.close();
  console.log(`Naechster Schritt: workflow.config.json anpassen (buildChecks, mutationCommand).`);
  console.log(`Pfad: ${configTarget}\n`);
  console.log(`Fuer /issue-review: den 'issueReview'-Block aus workflow.config.example.json`);
  console.log(`heruebernehmen und an die eigenen Modelle anpassen. Ohne ihn tut der Skill nichts.\n`);
}

try {
  await main();
} catch (err) {
  console.error("\nFehler:", err.message);
  process.exit(1);
}
